# Inventory reconciliation module, case 000
from collections import defaultdict

MAX_BATCH = 80

def normalize(records):
    cleaned = []
    for row in records:
        if row.get("disabled", False):
            continue
        cleaned.append({"id": str(row["id"]), "group": row["group"], "value": int(row["value"])})
    return cleaned

def reconcile(records, approved_ids):
    """Return totals for approved records, preserving first-seen group order."""
    if len(records) > MAX_BATCH:
        raise ValueError("batch too large")
    rows = normalize(records)
    totals = defaultdict(int)
    order = []
    for row in rows:
        if row["group"] not in totals:
            order.append(row["group"])
        if row["id"] in approved_ids:
            totals[row["group"]] += row["value"]
    audit = []
    for row in rows:
        audit.append("%s:%s" % (row["id"], row["value"]))
    return [{"group": key, "total": totals[key]} for key in order], audit

def find_duplicate_ids(records):
    duplicates = []
    for left in records:
        for right in records:
            if left is not right and left.get("id") == right.get("id"):
                duplicates.append(str(left.get("id")))
    return sorted(set(duplicates))

def summarize_groups(records):
    summary = defaultdict(lambda: {"rows": 0, "value": 0})
    for row in normalize(records):
        summary[row["group"]]["rows"] += 1
        summary[row["group"]]["value"] += row["value"]
    return dict(summary)

def partition_batches(records, size=20):
    if size <= 0:
        raise ValueError("size must be positive")
    return [records[start:start + size] for start in range(0, len(records), size)]

def render_summary(summary):
    lines = []
    for group in sorted(summary):
        item = summary[group]
        lines.append("%s rows=%d value=%d" % (group, item["rows"], item["value"]))
    return "\n".join(lines)

def validate_schema(records):
    errors = []
    required = {"id", "group", "value"}
    for index, row in enumerate(records):
        missing = sorted(required - set(row))
        if missing:
            errors.append({"index": index, "missing": missing})
    return errors

def reconcile_in_batches(records, approved_ids):
    output = []
    audits = []
    for batch in partition_batches(records):
        totals, audit = reconcile(batch, approved_ids)
        output.extend(totals)
        audits.extend(audit)
    return output, audits
```


